# AI use: Generated by Claude, Reviewed & Approved by Me
"""US5: vendors manage their own listings (view, edit, cancel, see who reserved)."""
from flask import Blueprint, abort, flash, redirect, render_template, request, url_for
from flask_login import current_user, login_required
from sqlalchemy import select
from sqlalchemy.exc import SQLAlchemyError
from werkzeug.datastructures import MultiDict

from .extensions import db
from .listings import validate_listing_form
from .models import DietaryTag, Listing, ReservationStatus
from .pickups import mark_no_shows

my_listings_bp = Blueprint("my_listings", __name__)


def _vendor_only():
    if current_user.role != "vendor":
        abort(403, description="Only vendors can manage listings.")


def _own_listing(listing_id, lock=False):
    """The vendor's own listing, or 404 so other vendors' listings look missing (AC 5)."""
    listing = db.session.get(Listing, listing_id, with_for_update=lock)
    if listing is None or listing.vendor_id != current_user.id:
        abort(404, description="Listing not found.")
    return listing


def _reserved(listing):
    """Portions held by students: US4 subtracts on reserve, US6 adds back on cancel."""
    return listing.portions - listing.portions_remaining


def _form_from(listing):
    """Pre-fill the edit form from the saved listing."""
    fmt = "%Y-%m-%dT%H:%M"
    return MultiDict([
        ("title", listing.title), ("description", listing.description),
        ("portions", str(listing.portions)), ("pickup_location", listing.pickup_location),
        ("pickup_start", listing.pickup_start.strftime(fmt)),
        ("pickup_end", listing.pickup_end.strftime(fmt)),
    ] + [("tags", tag.name) for tag in listing.tags])


@my_listings_bp.get("/my-listings")
@login_required
def my_listings():
    """AC 1: every listing of mine, with status and portions reserved / remaining."""
    _vendor_only()
    mark_no_shows(current_user.id)  # US7: store no-shows before showing statuses
    db.session.commit()
    listings = db.session.scalars(
        select(Listing).where(Listing.vendor_id == current_user.id)
        .order_by(Listing.pickup_start.desc())
    ).all()
    return render_template("my_listings.html", listings=listings, reserved=_reserved)


@my_listings_bp.get("/my-listings/<int:listing_id>")
@login_required
def listing_detail(listing_id):
    """AC 5: who reserved (name, portions, status)."""
    _vendor_only()
    mark_no_shows(current_user.id)  # US7: store no-shows before showing statuses
    db.session.commit()
    listing = _own_listing(listing_id)
    reservations = sorted(listing.reservations, key=lambda r: r.created_at)
    return render_template("listing_detail.html", listing=listing,
                           reservations=reservations, reserved=_reserved(listing))


@my_listings_bp.route("/my-listings/<int:listing_id>/edit", methods=["GET", "POST"])
@login_required
def edit_listing(listing_id):
    """AC 2 + 3: edit with US2's rules; portions can't go below what's reserved."""
    _vendor_only()
    listing = _own_listing(listing_id, lock=request.method == "POST")
    if listing.status != "active":
        db.session.rollback()
        flash("Only active listings can be edited.", "error")
        return redirect(url_for("my_listings.listing_detail", listing_id=listing_id))

    reserved = _reserved(listing)

    def show_form(form, status=200):
        return render_template("edit_listing.html", listing=listing, form=form,
                               dietary_tags=list(DietaryTag), reserved=reserved), status

    if request.method == "GET":
        return show_form(_form_from(listing))

    values, errors = validate_listing_form(request.form, original_start=listing.pickup_start)
    if values["portions"] is not None and values["portions"] < reserved:
        errors.append(f"Portions can't be lower than the {reserved} already reserved.")
    if errors:
        db.session.rollback()  # release the row lock
        for error in errors:
            flash(error, "error")
        return show_form(request.form, 400)

    for field, value in values.items():
        setattr(listing, field, value)
    listing.portions_remaining = values["portions"] - reserved
    try:
        db.session.commit()
    except SQLAlchemyError:
        db.session.rollback()
        flash("Something went wrong saving this listing. Please try again.", "error")
        return show_form(request.form, 500)

    flash("Listing updated.", "success")
    return redirect(url_for("my_listings.listing_detail", listing_id=listing_id))


@my_listings_bp.post("/my-listings/<int:listing_id>/cancel")
@login_required
def cancel_listing(listing_id):
    """AC 4: hide the listing from students and cancel its active reservations."""
    _vendor_only()
    listing = _own_listing(listing_id, lock=True)
    if listing.status != "active":
        db.session.rollback()
        flash("Only active listings can be cancelled.", "error")
        return redirect(url_for("my_listings.listing_detail", listing_id=listing_id))

    listing.cancelled = True
    cancelled = 0
    for reservation in listing.reservations:
        if reservation.status == ReservationStatus.ACTIVE:
            reservation.status = ReservationStatus.CANCELLED
            listing.portions_remaining += reservation.portions  # same as US6
            cancelled += 1
    try:
        db.session.commit()
    except SQLAlchemyError:
        db.session.rollback()
        flash("Something went wrong cancelling this listing. Please try again.", "error")
        return redirect(url_for("my_listings.listing_detail", listing_id=listing_id))

    flash(f"Listing cancelled. {cancelled} active reservation(s) were cancelled.", "success")
    return redirect(url_for("my_listings.listing_detail", listing_id=listing_id))
